const observations={
  route:'People use the route to reach nearby places.|Travelers recognize the route by name.|The route is part of everyday movement through the area.|People passing through pause to check their directions.|The route gives walkers a way through the district.|Visitors ask about the way ahead.|People use the route when describing how to find a place.|Regular travelers recognize its turns and approaches.|The route gives people a place to meet before continuing.|People coming from different directions meet along the way.',
  flowing:'The movement of the water draws the eye.|The banks provide a reference when giving directions.|The water follows the shape of its course.|Reflections break where the current moves.|The edge of the water gives walkers a line to follow.|People notice changes in the water’s movement.|Ripples mark the passage of the current.|The banks separate the water from neighboring ground.|The watercourse is a familiar local landmark.|Visitors pause to look along the water.',
  still:'The shore encloses an area of standing water.|Reflections move across the surface.|The water’s edge gives walkers a place to pause.|People recognize the water by its surrounding shore.|Small ripples disturb the reflections.|The shore gives visitors a reference for directions.|The water forms a break in the surrounding land.|Visitors look across the water from its edge.|The surface changes with passing breezes.|The surrounding ground meets the water along the shore.',
  coastal:'The shores help travelers judge their bearings.|Visitors look out across the water.|The water is part of the coastal landscape.|People recognize the place by the shape of the shore.|The coast provides reference points for travelers.|The meeting of land and water defines the view.|The shoreline gives people a way to describe the place.|Visitors pause to watch movement on the water.|People use the nearby shore to get their bearings.|The water continues between the surrounding coastal features.',
  woodland:'The tree line marks a change in the landscape.|Tree cover gives the ground patches of shade.|The edge of the woodland is a familiar landmark.|Visitors notice the change from open ground to trees.|Fallen leaves and twigs collect beneath the trees.|The trees shape the view through the woodland.|People use the tree line when giving directions.|The woodland breaks up the surrounding open land.|The growth of the trees gives the place its character.|Visitors pause to look between the trees.',
  heights:'The raised ground gives the place a recognizable outline.|People use its profile when finding their bearings.|The slopes change the shape of the surrounding land.|Visitors notice the rise from the lower ground.|The height is a familiar reference for travelers.|People recognize the place from its outline.|The change in elevation affects the way people approach.|Its profile stands out from neighboring ground.|Travelers use the higher ground as a reference point.|The slopes form part of the local landscape.',
  valley:'The lower ground follows the shape of the surrounding slopes.|Higher ground frames the view.|People use the valley’s shape to describe directions.|The land descends into the lower ground.|Visitors recognize the place by the enclosing slopes.|The valley gives the landscape a clear change in height.|Travelers take account of the slopes when finding their way.|The lower ground is a familiar local reference.|The surrounding heights define the valley’s outline.|The shape of the land guides people through the area.',
  marsh:'Wet ground shapes the way people approach.|Visitors pay attention to firmer patches of ground.|The waterlogged area breaks up the surrounding landscape.|People use the edge of the wet ground as a reference.|The soft ground calls for care when walking nearby.|Visitors look for firm footing at the margins.|The damp ground gives the place its character.|People take account of the wet ground when giving directions.|The marsh is a recognizable feature of the area.|The margins mark a change from wetter to firmer land.',
  field:'The worked ground is part of the local growing landscape.|The edges distinguish the field from neighboring land.|People recognize the holding by its boundaries.|The open ground gives a clear view across the holding.|The field forms part of the area’s agricultural life.|Visitors use the edge of the worked land as a reference.|The land is tended as an agricultural holding.|The field’s boundaries shape the surrounding landscape.|People take account of the worked ground when passing nearby.|The open holding is a familiar local reference.',
  shore:'The meeting of land and water shapes the place.|The shore is a familiar reference for travelers.|Visitors recognize the place by the coastal outline.|The edge of the land gives people a view over the water.|The shape of the shore helps people find their bearings.|Visitors look along the meeting of land and water.|People use the coastal edge when describing directions.|The shoreline forms part of the local landscape.|The land ends against the neighboring water.|The coast gives the place a recognizable outline.',
  cliff:'The exposed face marks a sharp change in height.|The edge calls for care when walking nearby.|Visitors recognize the place by its steep outline.|The drop changes the shape of the surrounding ground.|People use the cliff’s profile as a landmark.|The exposed face stands above lower ground.|Visitors keep track of the edge when finding their way.|The change in height is visible in the landscape.|The steep face gives the place its character.|People take account of the drop when describing an approach.',
  island:'Water surrounds the tract of land.|The shore gives the island a recognizable outline.|Visitors recognize the island by its profile.|The island is a reference point in the surrounding waters.|Its edges meet the water on every side.|The land forms a distinct part of the surrounding waterscape.|The island’s outline is a familiar landmark.|People use the island as a reference when describing the area.|The surrounding water separates it from neighboring land.|Its shore defines the edge of the holding.'
};
const activities={
  street:'A walker pauses to check the way ahead.|A messenger asks for directions.|Two travelers stop to compare their routes.|A local guide waits for a companion.|A visitor studies the approach.|A courier takes a short rest.|Neighbors pause to exchange news.|A traveler checks a small sketch map.|A local resident gives a visitor directions.|A group gathers before continuing its journey.',
  water:'A visitor watches the water.|A local guide points out the water’s edge.|A walker pauses near the shore.|A visitor sketches the outline of the bank.|Two travelers compare their bearings.|A local resident answers a question about the water.|A visitor studies the reflections.|A walker looks for a place to pause nearby.|A traveler checks the name on a small chart.|A visitor asks about changes in the water level.',
  terrain:'A walker pauses to get their bearings.|A local guide points out the shape of the ground.|A visitor sketches the outline of the landscape.|Two travelers compare their directions.|A visitor asks how the place got its name.|A local resident describes the nearby ground.|A traveler consults a small map.|A walker stops to look at the surroundings.|A guide waits for a companion.|A visitor asks about the way ahead.'
};
const groups={street:'route',road:'route',lane:'route',alley:'route',bridge:'route',square:'route',trail:'route',river:'flowing',stream:'flowing',canal:'flowing',lake:'still',pond:'still',bay:'coastal',sea:'coastal',channel:'coastal',strait:'coastal',forest:'woodland',wood:'woodland',hill:'heights',mountain:'heights',valley:'valley',marsh:'marsh',field:'field',beach:'shore',cape:'shore',cliff:'cliff',island:'island'};
export const geographySources=Object.fromEntries(Object.entries(groups).map(([kind,group])=>{
  const category=['route'].includes(group)?'street':['flowing','still','coastal'].includes(group)?'water':'terrain';
  return [kind,recipe(observations[group],activities[category])];
}));
const visitors='A visiting traveler|A local guide|A returning visitor|A walker|A local resident|A messenger|A neighbor|A young traveler|A visiting artist|A courier';
export const geographyNotes={
  routeNotes:recipe(visitors,'is asking for directions along {displayName}.|is comparing two ways to reach {displayName}.|is sketching an approach to {displayName}.|is arranging to meet a companion at {displayName}.|is checking a name used for {displayName}.|is asking about the route beyond {displayName}.|is waiting for a companion near {displayName}.|is comparing an old description with {displayName}.|is looking for a guide near {displayName}.|is asking how people used {displayName} in earlier years.'),
  waterNotes:recipe(visitors,'is sketching the edge of {displayName}.|is asking how {displayName} got its name.|is comparing the outline of {displayName} with an old drawing.|is looking across {displayName} for a familiar landmark.|is asking about changes in the level of {displayName}.|is waiting for a companion near {displayName}.|is watching the surface of {displayName}.|is asking about the neighboring shores of {displayName}.|is checking the name of {displayName} on a chart.|is asking a local guide about {displayName}.'),
  terrainNotes:recipe(visitors,'is sketching the outline of {displayName}.|is asking how {displayName} got its name.|is comparing {displayName} with an older description.|is asking about the edges of {displayName}.|is finding their bearings near {displayName}.|is waiting for a companion near {displayName}.|is asking about the way around {displayName}.|is checking the name of {displayName} on a map.|is asking a local guide about {displayName}.|is looking at the shape of the ground near {displayName}.')
};
const goals={
  street:'return a parcel dropped near {displayName}|find the owner of a lost walking stick near {displayName}|carry a message to a guide waiting at {displayName}|compare an older route description with {displayName}|ask a longtime resident about an earlier name for {displayName}|help a traveler find their way to {displayName}|look for a missing direction marker near {displayName}|return a sketch map found at {displayName}|find a companion expected at {displayName}|ask who tends the approach to {displayName}',
  water:'find the owner of a basket left near {displayName}|compare a sketch of {displayName} with its shore|find a guide who knows {displayName}|return a chart found near {displayName}|look for a lost fishing float near {displayName}|ask a longtime resident about an older name for {displayName}|carry a message to a visitor waiting near {displayName}|copy a faded place name from a chart of {displayName}|ask a local resident about changes at {displayName}|help locate a traveler’s pack left near {displayName}',
  terrain:'ask a longtime resident about an older name for {displayName}|return a sketch found near {displayName}|find a guide familiar with {displayName}|help locate a pack left near {displayName}|compare an older description with {displayName}|find a companion expected near {displayName}|ask who looks after the edge of {displayName}|return a walking stick found near {displayName}|carry a message to a guide waiting near {displayName}|help a traveler find their way to {displayName}'
};
const requests='A traveler asks someone to|A local guide wants someone to|A neighbor is looking for someone to|A visitor wants someone to|A returning traveler has asked someone to|A local resident is seeking someone to|A messenger brings a request to|A visiting artist asks someone to|A walker needs someone to|A guide would like someone to';
export const geographyRumors=Object.fromEntries(Object.entries(goals).map(([category,values])=>[category,recipe(requests,values.split('|').map(v=>`${v}.`))]));
export function geographyProse(place,tokens,draw) {
  const kind=place.type || place.category,category=place.category;
  const source=geographySources[kind] || recipe(observations[category==='water'?'still':category==='street'?'route':'heights'],activities[category]);
  const opening=summaries[kind]?`${tokens.displayName} ${summaries[kind]} in ${tokens.district}.`:`${tokens.displayName} is part of ${tokens.district}.`;
  const setting=place.context?.water?` It adjoins ${tokens.water}.`:place.context?.terrain?` It lies near ${tokens.terrain}.`:'';
  return {description:`${opening} ${draw('landscape',source)}${setting}`,rumor:draw('landscape-lead',geographyRumors[category]),person:'',services:''};
}
